import {ZONE_REGISTRY} from './unified-world-registry.js';import {zoneLabel} from './unified-world-layout.js';
/** Reuse actual camera controls and object-list nodes, with real HTML disclosures.
 * @param {{host:HTMLElement,bar:HTMLElement,minimap:HTMLDetailsElement,weather:Element|null}} options */
export function createWorldTools(options){
 const {host,bar}=options,toolbar=host.querySelector('.unified-preview-controls'),list=host.querySelector('ul'),instructions=host.querySelector('p:last-of-type'),abort=new AbortController();
 if(!(toolbar instanceof HTMLElement)||!(list instanceof HTMLUListElement))throw Error('Original world alternatives unavailable');
 /** @param {string} id @param {Element[]} nodes */
 function disclosure(id,nodes){const root=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('section'),header=document.createElement('div'),title=document.createElement('h3'),close=document.createElement('button');root.id=id;root.className='world-tool-disclosure';summary.setAttribute('aria-controls',id+'-panel');body.id=id+'-panel';body.className='world-tool-panel';body.setAttribute('aria-labelledby',id+'-title');title.id=id+'-title';header.className='world-tool-heading';close.type='button';close.className='close-panel';close.textContent='×';close.dataset.worldToolClose=id;close.addEventListener('click',()=>{root.open=false;syncLayer();summary.focus({preventScroll:true});},{signal:abort.signal});header.append(title,close);body.append(header,...nodes);root.append(summary,body);bar.append(root);return{root,summary,body,title,close};}
 const legend=host.querySelector('#world-mission-legend'),retry=host.querySelector('[data-preview-retry]'),camera=disclosure('world-camera-tools',[instructions,legend,toolbar].filter(n=>n instanceof Element)),objects=disclosure('world-objects',[]),searchLabel=document.createElement('label'),searchCopy=document.createElement('span'),search=document.createElement('input'),filter=document.createElement('select'),empty=document.createElement('p');search.type='search';search.id='world-object-search';searchLabel.htmlFor=search.id;searchLabel.className='world-object-search';searchLabel.append(searchCopy,search);filter.id='world-object-zone';for(const zone of ['all',...Object.keys(ZONE_REGISTRY)]){const option=document.createElement('option');option.value=zone;filter.append(option);}list.id='world-object-list';empty.className='world-object-empty';empty.hidden=true;objects.body.append(searchLabel,filter,empty,list);
 const roots=[camera.root,objects.root,options.minimap,...(options.weather instanceof HTMLDetailsElement?[options.weather]:[])];
 /** Event-driven popup stacking; no frame-dependent relational selector. */
 function syncLayer(){bar.classList.toggle('world-tools-open',roots.some(root=>bar.contains(root)&&root.open));}
 /** @param {HTMLDetailsElement|null} [except] */
 function closeOthers(except=null){for(const root of roots)if(root!==except)root.open=false;syncLayer();}
 function applyFilter(){const query=search.value.trim().toLocaleLowerCase();let visible=0;for(const item of list?.children||[]){if(!(item instanceof HTMLElement))continue;const match=(!query||item.textContent?.toLocaleLowerCase().includes(query))&&(filter.value==='all'||item.dataset.previewEntity?.startsWith(filter.value+'.'));item.hidden=!match;if(match)visible++;}empty.hidden=visible>0;}
 search.addEventListener('input',applyFilter,{signal:abort.signal});filter.addEventListener('change',applyFilter,{signal:abort.signal});toolbar.addEventListener('click',event=>{if(!(event.target instanceof Element)||!event.target.closest('[data-preview-camera]'))return;camera.root.open=false;syncLayer();host.querySelector('canvas')?.focus({preventScroll:true});},{signal:abort.signal});list.addEventListener('click',event=>{if(event.target instanceof Element&&event.target.closest('[data-preview-select]')){objects.root.open=false;syncLayer();}},{signal:abort.signal});
 for(const root of roots)root.addEventListener('toggle',()=>{if(root.open){closeOthers(root);if(root===objects.root){applyFilter();search.focus({preventScroll:true});}}syncLayer();},{signal:abort.signal});
 document.addEventListener('pointerdown',event=>{if(!(event.target instanceof Node))return;for(const root of roots)if(root.open&&!root.contains(event.target))root.open=false;syncLayer();},{capture:true,signal:abort.signal});
 document.addEventListener('keydown',event=>{if(event.key!=='Escape'||document.querySelector('dialog[open]'))return;const open=roots.find(root=>root.open);if(!open)return;event.preventDefault();event.stopPropagation();open.open=false;syncLayer();open.querySelector('summary')?.focus({preventScroll:true});},{capture:true,signal:abort.signal});
 retry?.addEventListener('click',()=>{camera.root.open=false;host.querySelector('canvas')?.focus({preventScroll:true});},{signal:abort.signal});
 syncLayer();let language='';return{
  /** @param {string} locale */
  update(locale){const id=locale==='id';if(language!==locale){search.value='';language=locale;}camera.summary.textContent=id?'Kamera':'Camera';camera.title.textContent=id?'Kontrol kamera':'Camera controls';camera.close.setAttribute('aria-label',id?'Tutup kontrol kamera':'Close camera controls');objects.summary.textContent=id?'Objek':'Objects';objects.title.textContent=id?'Pilih objek farm':'Choose a farm object';objects.close.setAttribute('aria-label',id?'Tutup daftar objek':'Close object list');searchCopy.textContent=id?'Cari objek':'Find an object';search.placeholder=id?'Nama objek atau area':'Object or area name';filter.setAttribute('aria-label',id?'Filter area':'Filter area');for(const option of filter.options)option.textContent=option.value==='all'?(id?'Semua area':'All areas'):zoneLabel(option.value,locale);empty.textContent=id?'Objek tidak ditemukan. Coba nama lain atau semua area.':'No matching objects. Try another name or all areas.';applyFilter();},
  close:closeOthers,
  dispose(){abort.abort();closeOthers();}
 };
}
